const { readdirSync, readFileSync } = require('node:fs');
const { join, dirname, resolve, relative } = require('node:path');

function collectFiles(dir, exts) {
  const files = [];
  function scan(d) {
    readdirSync(d, { withFileTypes: true }).forEach(e => {
      const p = join(d, e.name);
      if (e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules') scan(p);
      else if (e.isFile() && exts.some(ext => e.name.endsWith(ext))) files.push(p);
    });
  }
  scan(dir);
  return files;
}

function resolveAlias(spec, aliases) {
  for (const [k, v] of Object.entries(aliases)) {
      if (spec.startsWith(k)) return spec.replace(k, v);
  }
  return null;
}

function findExporter(name, root) {
  for (const f of collectFiles(root, ['.ts', '.tsx', '.vue', '.js'])) {
    const rx = new RegExp(`export\s+(?:default\s+)?(?:class|function|const|let|var)?\s*${name}\b|export\s+{[^}]*\b${name}\b[^}]*}`, 'm');
    if (rx.test(readFileSync(f, 'utf-8'))) return f;
  }
  return null;
}

function relPath(from, to) {
  const r = relative(dirname(from), to).replace(/\\/g, '/').replace(/\.[^./]+$/, '');
  return r.startsWith('.') ? r : './' + r;
}

const patches = [];
const root = resolve(input.rootDir || '.');

for (const imp of input.broken_imports) {
  const aliased = resolveAlias(imp.specifier, input.aliases);
  if (aliased) {
    const name = aliased.split('/').pop();
    const exporter = findExporter(name, root);
    if (exporter) {
      patches.push({ file: imp.file, line: imp.line, from: imp.specifier, to: relPath(imp.file, exporter) });
    }
  }
}

return { patches };
